package sourcenoise

import (
	"strings"
	"time"
)

// ArtTrack is what an Art Track upload's auto-generated description states
// about its recording. Released is a YYYY-MM-DD date or empty.
type ArtTrack struct {
	Title    string
	Artists  []string
	Album    string
	Released string
}

const (
	providedPrefix  = "Provided to YouTube by "
	artistSeparator = " \u00b7 "
	releasedPrefix  = "Released on:"
	autoGenerated   = "Auto-generated by YouTube."
)

// ParseArtTrackDescription reads the description YouTube generates for an Art
// Track upload:
//
//	Provided to YouTube by <label>
//
//	<Title> * <Artist>[ * <Artist>...]
//
//	<Album>
//
//	[(P) and (C) lines, "Released on: YYYY-MM-DD", "Role: Name" credits,
//	"Auto-generated by YouTube."]
//
// where * is U+00B7 with a space each side.
// The three header blocks are strict, since what it returns is written into a
// file's tags; anything after the album is read only for the release date.
func ParseArtTrackDescription(desc string) (ArtTrack, bool) {
	blocks := splitBlocks(desc)
	if len(blocks) < 3 {
		return ArtTrack{}, false
	}
	provided, titleBlock, albumBlock := blocks[0], blocks[1], blocks[2]
	if len(provided) != 1 || len(titleBlock) != 1 || len(albumBlock) != 1 {
		return ArtTrack{}, false
	}
	if label, ok := strings.CutPrefix(provided[0], providedPrefix); !ok || strings.TrimSpace(label) == "" {
		return ArtTrack{}, false
	}
	parts := strings.Split(titleBlock[0], artistSeparator)
	if len(parts) < 2 {
		return ArtTrack{}, false
	}
	for i, p := range parts {
		parts[i] = strings.TrimSpace(p)
		if parts[i] == "" {
			return ArtTrack{}, false
		}
	}
	// The album is the third block by position: only a marked trailer line
	// there says it is missing. An album may read "Words: Subtitle", as a
	// credit does.
	album := albumBlock[0]
	if isTrailerLine(album) {
		return ArtTrack{}, false
	}
	at := ArtTrack{Title: parts[0], Artists: parts[1:], Album: album}
	// What follows the album (copyrights, credits of every shape, the closing
	// note) is read past; only the release date is taken from it.
	for _, block := range blocks[3:] {
		for _, line := range block {
			if v, ok := strings.CutPrefix(line, releasedPrefix); ok {
				at.Released = releaseDate(strings.TrimSpace(v))
			}
		}
	}
	return at, true
}

// splitBlocks splits desc into blank-line separated blocks of trimmed lines.
func splitBlocks(desc string) [][]string {
	desc = strings.ReplaceAll(desc, "\r\n", "\n")
	desc = strings.ReplaceAll(desc, "\r", "\n")
	var blocks [][]string
	var cur []string
	for line := range strings.SplitSeq(desc, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			if cur != nil {
				blocks = append(blocks, cur)
				cur = nil
			}
			continue
		}
		cur = append(cur, line)
	}
	if cur != nil {
		blocks = append(blocks, cur)
	}
	return blocks
}

// isTrailerLine reports whether a line is one of the marked lines that follow
// the album: a copyright, the release date, or the closing note.
func isTrailerLine(line string) bool {
	return strings.HasPrefix(line, "\u2117") || strings.HasPrefix(line, "\u00a9") ||
		strings.HasPrefix(line, releasedPrefix) || line == autoGenerated
}

func releaseDate(v string) string {
	if len(v) != len("2006-01-02") {
		return ""
	}
	if _, err := time.Parse("2006-01-02", v); err != nil {
		return ""
	}
	return v
}
